import org.apache.tika.Tika;
import java.io.*;

public class TikaAnalysis {
    public static void main(String[] args) throws Exception {
        Tika tika = new Tika();
        File testFile = new File("/tmp/test-document.txt");

        System.out.println("Starting Tika analysis loop...");
        // Create a test PDF-like file for more interesting parsing
        byte[] pdfHeader = "%PDF-1.4\n1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n".getBytes();
