        fos.write("2 0 obj\n<< /Type /Pages /Kids [] /Count 0 >>\nendobj\n".getBytes());
        fos.write("xref\n0 3\n0000000000 65535 f \n0000000009 00000 n \n0000000058 00000 n \n".getBytes());
        fos.write("trailer << /Size 3 /Root 1 0 R >>\nstartxref\n128\n%%EOF".getBytes());
        fos.close();
        File pdfFile = new File("/tmp/test-document.pdf");

        // Create an HTML file
        FileWriter fw = new FileWriter("/tmp/test-document.html");
        fw.write("<html><head><title>Test Document</title></head><body><h1>Hello Tika</h1><p>This is a test HTML document for content analysis.</p></body></html>");
        fw.close();
        File htmlFile = new File("/tmp/test-document.html");

        for (int i = 0; i < 1000; i++) {
            String txtContent = tika.parseToString(testFile);
            String txtType = tika.detect(testFile);
            String pdfType = tika.detect(pdfFile);
            String htmlContent = tika.parseToString(htmlFile);
            String htmlType = tika.detect(htmlFile);
            System.out.println("Iteration " + i + ": txt=" + txtType + ", pdf=" + pdfType + ", html=" + htmlType);
            Thread.sleep(100);
        }
        System.out.println("Tika analysis loop completed.");
    }
}
